<script>
import { adminApi } from "../../services/adminApi";
export default { data(){return {loading:true,error:"",items:[]}}, async mounted(){try{this.items=await adminApi.get("tenants")}catch(e){this.error=e.response?.data?.message||"Não foi possível carregar os dados."}finally{this.loading=false}}, methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},date(v){return v?new Date(v).toLocaleDateString("pt-BR"):"—"}}}
</script><template><div><h4>Músicos / Tenants</h4><p class="text-muted">Contas artísticas, plano, assinatura e situação operacional.</p><div class="card"><div class="card-body"><div v-if="loading" class="text-center py-4"><div class="spinner-border text-primary"></div></div><div v-else class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Artista</th><th>Plano</th><th>Perfil</th><th>Assinatura</th><th>Asaas/KYC</th><th>Pacotes</th><th>Shows</th></tr></thead><tbody><tr v-for="x in items" :key="x.id"><td><strong>{{x.name}}</strong><div class="text-muted small">{{x.email}}</div></td><td>{{x.planName||'Sem plano'}}</td><td><span class="badge bg-secondary-subtle text-secondary">{{x.profileStatus}}</span></td><td>{{x.subscriptionStatus}}</td><td>{{x.asaasAccountStatus}}</td><td>{{x.packages}}</td><td>{{x.shows}}</td></tr></tbody></table></div><div v-if="error" class="alert alert-danger">{{error}}</div></div></div></div></template>